import random
import time
import itertools

def construct():
    points = list(range(16))
    all_triples = list(itertools.combinations(points, 3))
    num_triples = len(all_triples)
    
    # Map triple to index
    triple_to_idx = {t: i for i, t in enumerate(all_triples)}
    
    # Precompute hyperedges (K(2,2,2) configurations)
    # A hyperedge is a set of 8 triples.
    # Generated by choosing 6 distinct points and partitioning into 3 pairs.
    hyperedges = []
    triple_to_hyperedges = [[] for _ in range(num_triples)]
    
    # Iterate over all combinations of 6 points
    for p6 in itertools.combinations(points, 6):
        # p6 is (p0, p1, p2, p3, p4, p5)
        # Partitions of 6 items into 3 pairs (15 ways)
        partitions = [
            [(0,1),(2,3),(4,5)],
            [(0,1),(2,4),(3,5)],
            [(0,1),(2,5),(3,4)],
            [(0,2),(1,3),(4,5)],
            [(0,2),(1,4),(3,5)],
            [(0,2),(1,5),(3,4)],
            [(0,3),(1,2),(4,5)],
            [(0,3),(1,4),(2,5)],
            [(0,3),(1,5),(2,4)],
            [(0,4),(1,2),(3,5)],
            [(0,4),(1,3),(2,5)],
            [(0,4),(1,5),(2,3)],
            [(0,5),(1,2),(3,4)],
            [(0,5),(1,3),(2,4)],
            [(0,5),(1,4),(2,3)]
        ]
        
        for part in partitions:
            pairs = []
            for r1, r2 in part:
                pairs.append((p6[r1], p6[r2]))
            
            # Generate 8 triples
            h_triples = []
            for i in range(2):
                for j in range(2):
                    for k in range(2):
                        a = pairs[0][0] if i == 0 else pairs[0][1]
                        b = pairs[1][0] if j == 0 else pairs[1][1]
                        c = pairs[2][0] if k == 0 else pairs[2][1]
                        t = tuple(sorted((a, b, c)))
                        h_triples.append(t)
            
            # Convert to indices
            h_indices = [triple_to_idx[t] for t in h_triples]
            hyperedges.append(h_indices)
            
            # Update triple_to_hyperedges
            h_idx = len(hyperedges) - 1
            for t_idx in h_indices:
                triple_to_hyperedges[t_idx].append(h_idx)
                
    num_hyperedges = len(hyperedges)
    
    best_set = set()
    best_size = 0
    start_time = time.time()
    time_limit = 115
    
    random.seed(42)
    
    def is_valid_add(t_idx, counts):
        # Check if adding t_idx violates any hyperedge
        for h_idx in triple_to_hyperedges[t_idx]:
            if counts[h_idx] == 7:
                return False
        return True

    def greedy_fill(current_set, counts):
        """
        Incremental greedy fill.
        Maintains a set of 'available' triples that are not in current_set 
        and are currently valid to add.
        """
        # Initialize available set with all triples not in current_set that are valid
        available = set()
        for t_idx in range(num_triples):
            if t_idx not in current_set:
                if is_valid_add(t_idx, counts):
                    available.add(t_idx)
        
        while available:
            # Pick a random available triple to introduce randomness and avoid deterministic traps
            t_idx = random.choice(list(available))
            available.remove(t_idx)
            
            # Add it
            current_set.add(t_idx)
            
            # Update counts
            for h_idx in triple_to_hyperedges[t_idx]:
                counts[h_idx] += 1
            
            # Update available set
            # Any triple sharing a hyperedge with t_idx might now be invalid
            # Also, we just removed t_idx from available, so no need to check it again
            to_remove = []
            for neighbor_t in available:
                # Check if neighbor_t is now invalid due to this addition
                # It is invalid if any of its hyperedges is now full (count == 7)
                # Note: counts were incremented. If a hyperedge count becomes 7, 
                # any other triple in that hyperedge (not already in set) becomes invalid.
                # We can optimize by checking if any h_idx in triple_to_hyperedges[neighbor_t] 
                # has count 7.
                # However, iterating through all available neighbors is expensive.
                # Instead, we can just re-check validity of neighbors of t_idx?
                # Actually, adding t_idx only affects triples that share a hyperedge with t_idx.
                # So we only need to check triples in `available` that share a hyperedge with t_idx.
                pass # This logic is complex to optimize simply. 
            # Simpler approach: Just re-evaluate validity for all available? 
            # That's back to O(N). 
            # Let's stick to the simpler "scan all available" but it's O(|Available| * Degree).
            # Given N=560, this is fine.
            
            new_available = set()
            for neighbor_t in available:
                if is_valid_add(neighbor_t, counts):
                    new_available.add(neighbor_t)
            available = new_available
            
        return current_set, counts

    def random_greedy_init():
        """
        Creates a random initial set by shuffling triples and adding if valid.
        """
        current_set = set()
        counts = [0] * num_hyperedges
        indices = list(range(num_triples))
        random.shuffle(indices)
        for t_idx in indices:
            if is_valid_add(t_idx, counts):
                current_set.add(t_idx)
                for h_idx in triple_to_hyperedges[t_idx]:
                    counts[h_idx] += 1
        return current_set, counts

    def perturb(current_set, counts, k):
        """
        Removes k random triples from current_set.
        """
        new_set = set(current_set)
        new_counts = list(counts)
        
        if not new_set:
            return new_set, new_counts
            
        items = list(new_set)
        random.shuffle(items)
        num_to_remove = min(k, len(items))
        
        for i in range(num_to_remove):
            t_idx = items[i]
            new_set.discard(t_idx)
            for h_idx in triple_to_hyperedges[t_idx]:
                new_counts[h_idx] -= 1
                
        return new_set, new_counts

    # Main ILS Loop
    current_set, current_counts = random_greedy_init()
    current_set, current_counts = greedy_fill(current_set, current_counts)
    
    if len(current_set) > best_size:
        best_size = len(current_set)
        best_set = set(current_set)
        
    perturbation_k = 10
    temperature = 1.0
    cooling = 0.999
    
    while time.time() - start_time < time_limit:
        # Perturb
        perturbed_set, perturbed_counts = perturb(current_set, current_counts, perturbation_k)
        
        # Local Search (Greedy Fill)
        new_set, new_counts = greedy_fill(perturbed_set, perturbed_counts)
        
        # Acceptance with Simulated Annealing
        delta = len(new_set) - len(current_set)
        
        if delta > 0:
            # Always accept improvements
            current_set = new_set
            current_counts = new_counts
            if len(current_set) > best_size:
                best_size = len(current_set)
                best_set = set(current_set)
        else:
            # Accept worse solutions with probability exp(delta / temperature)
            # delta is negative, so exp(negative) is < 1
            if random.random() < pow(2.71828, delta / temperature):
                current_set = new_set
                current_counts = new_counts
        
        # Cool down
        temperature *= cooling
        
        # Occasionally adjust perturbation strength
        if random.random() < 0.05:
            perturbation_k = random.randint(5, 25)
            
        # Restart if stuck for too long or temperature is very low
        if temperature < 0.01:
            # Restart with a new random initialization
            current_set, current_counts = random_greedy_init()
            current_set, current_counts = greedy_fill(current_set, current_counts)
            if len(current_set) > best_size:
                best_size = len(current_set)
                best_set = set(current_set)
            temperature = 1.0
            perturbation_k = 10

    # Convert best_set indices back to triples
    return [list(all_triples[i]) for i in best_set]
